/**
 * Remove points that are nearly colinear with others
 */
public void smoothPoints() {
    this.willChange();
    boolean removed = false;
    int n = this.fPoly.npoints;
    do {
        removed = false;
        int i = 0;
        while ((i < n) && (n >= 3)) {
            int nxt = (i + 1) % n;
            int prv = ((i - 1) + n) % n;
            if (CH.ifa.draw.contrib.PolygonFigure.distanceFromLine(this.fPoly.xpoints[prv], this.fPoly.ypoints[prv], this.fPoly.xpoints[nxt], this.fPoly.ypoints[nxt], this.fPoly.xpoints[i], this.fPoly.ypoints[i]) < CH.ifa.draw.contrib.PolygonFigure.TOO_CLOSE) {
                removed = true;
                --n;
                for (int j = i; j < n; ++j) {
                    this.fPoly.xpoints[j] = this.fPoly.xpoints[j + 1];
                    this.fPoly.ypoints[j] = this.fPoly.ypoints[j + 1];
                }
            } else {
                ++i;
            }
        } 
    } while (removed );
    if (n != this.fPoly.npoints) {
        this.fPoly = new java.awt.Polygon(this.fPoly.xpoints, this.fPoly.ypoints, n);
    }
    this.changed();
}

/**
 * Gets the handles of the figure.
 */
public java.util.Vector handles() {
    java.util.Vector handles = new java.util.Vector(this.fPoints.size() * 2);
    handles.addElement(new CH.ifa.draw.standard.ChangeConnectionStartHandle(this));
    for (int i = 1; i < (this.fPoints.size() - 1); i++) {
        handles.addElement(new CH.ifa.draw.standard.NullHandle(this, CH.ifa.draw.figures.PolyLineFigure.locator(i)));
    }
    handles.addElement(new CH.ifa.draw.standard.ChangeConnectionEndHandle(this));
    for (int i = 0; i < (this.fPoints.size() - 1); i++) {
        handles.addElement(new CH.ifa.draw.figures.ElbowHandle(this, i));
    }
    return handles;
}

