    CH.ifa.draw.framework.Figure target = this.findConnectableFigure(x, y, drawing);
    if (((((target != null) && target.canConnect()) && (target != this.fOriginalTarget)) && (!target.includes(this.owner()))) && this.fConnection.canConnect(this.source().owner(), target)) {
        return this.findConnector(x, y, target);
    }
    return null;
}

private CH.ifa.draw.framework.Figure findConnectableFigure(int x, int y, CH.ifa.draw.framework.Drawing drawing) {
    CH.ifa.draw.framework.FigureEnumeration k = drawing.figuresReverse();
    while (k.hasMoreElements()) {
        CH.ifa.draw.framework.Figure figure = k.nextFigure();
        if ((!figure.includes(this.fConnection)) && figure.canConnect()) {
            if (figure.containsPoint(x, y)) {
                return figure;
            }
        }
    } 
    return null;
}

