public void invokeStep(int x, int y, int anchorX, int anchorY, CH.ifa.draw.framework.DrawingView view) {
    CH.ifa.draw.figures.LineConnection line = this.ownerConnection();
    java.awt.Point p1 = line.pointAt(this.fSegment);
    java.awt.Point p2 = line.pointAt(this.fSegment + 1);
    int ddx = x - this.fLastX;
    int ddy = y - this.fLastY;
    java.awt.Point np1;
    java.awt.Point np2;
    if (this.isVertical(p1, p2)) {
        int cx = this.constrainX(p1.x + ddx);
        np1 = new java.awt.Point(cx, p1.y);
        np2 = new java.awt.Point(cx, p2.y);
    } else {
        int cy = this.constrainY(p1.y + ddy);
        np1 = new java.awt.Point(p1.x, cy);
        np2 = new java.awt.Point(p2.x, cy);
    }
    line.setPointAt(np1, this.fSegment);
    line.setPointAt(np2, this.fSegment + 1);
    this.fLastX = x;
    this.fLastY = y;
}

