    r.grow(2, 2);
    if (!r.contains(px, py)) {
        return false;
    }
    double a;
    double b;
    double x;
    double y;
    if (x1 == x2) {
        return java.lang.Math.abs(px - x1) < 3;
    }
    if (y1 == y2) {
        return java.lang.Math.abs(py - y1) < 3;
    }
    a = ((double) (y1 - y2)) / ((double) (x1 - x2));
    b = ((double) (y1)) - (a * ((double) (x1)));
    x = (py - b) / a;
    y = (a * px) + b;
    return java.lang.Math.min(java.lang.Math.abs(x - px), java.lang.Math.abs(y - py)) < 4;
}

