    CH.ifa.draw.samples.pert.PertFigure source = ((CH.ifa.draw.samples.pert.PertFigure) (start));
    CH.ifa.draw.samples.pert.PertFigure target = ((CH.ifa.draw.samples.pert.PertFigure) (end));
