 * Writes a string to the output stream. Special characters
 * are quoted.
 */
public void writeString(java.lang.String s) {
    this.fStream.print('"');
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        switch (c) {
            case '\n' :
                this.fStream.print('\\');
                this.fStream.print('n');
                break;
            case '"' :
                this.fStream.print('\\');
                this.fStream.print('"');
                break;
            case '\\' :
                this.fStream.print('\\');
                this.fStream.print('\\');
                break;
            case '\t' :
                this.fStream.print('\\');
                this.fStream.print('\t');
                break;
            default :
                this.fStream.print(c);
        }
    }
    this.fStream.print('"');
    this.space();
}

