    this.willChange();
    java.awt.Point start = this.startPoint();
    java.awt.Point end = this.endPoint();
    this.fPoints.removeAllElements();
    this.fPoints.addElement(start);
    if ((start.x == end.x) || (start.y == end.y)) {
        this.fPoints.addElement(end);
    } else {
        java.awt.Rectangle r1 = this.start().owner().displayBox();
        java.awt.Rectangle r2 = this.end().owner().displayBox();
        int x1;
        int y1;
        int x2;
        int y2;
        int dir = CH.ifa.draw.util.Geom.direction(r1.x + (r1.width / 2), r1.y + (r1.height / 2), r2.x + (r2.width / 2), r2.y + (r2.height / 2));
        if ((dir == CH.ifa.draw.util.Geom.NORTH) || (dir == CH.ifa.draw.util.Geom.SOUTH)) {
            this.fPoints.addElement(new java.awt.Point(start.x, (start.y + end.y) / 2));
            this.fPoints.addElement(new java.awt.Point(end.x, (start.y + end.y) / 2));
        } else {
            this.fPoints.addElement(new java.awt.Point((start.x + end.x) / 2, start.y));
            this.fPoints.addElement(new java.awt.Point((start.x + end.x) / 2, end.y));
        }
        this.fPoints.addElement(end);
    }
    this.changed();
}

