public void loadRegisteredImages(java.awt.Component component) {
    if (this.fRegisteredImages.size() == 0) {
        return;
    }
    java.awt.MediaTracker tracker = new java.awt.MediaTracker(component);
    // register images with MediaTracker
    java.util.Enumeration k = this.fRegisteredImages.elements();
    while (k.hasMoreElements()) {
        java.lang.String fileName = ((java.lang.String) (k.nextElement()));
        if (this.basicGetImage(fileName) == null) {
            tracker.addImage(this.loadImage(fileName), CH.ifa.draw.util.Iconkit.ID);
        }
    } 
    this.fRegisteredImages.removeAllElements();
    // block until all images are loaded
    try {
        tracker.waitForAll();
    } catch (java.lang.Exception e) {
    }
}

