    for (int i = 0; i < nmembers; i++) {
        java.awt.Component m = target.getComponent(i);
        if (m.isVisible()) {
            java.awt.Dimension d = m.getMinimumSize();
            if (this.fVerticalLayout) {
                dim.width = java.lang.Math.max(dim.width, d.width);
                if (i > 0) {
                    dim.height += this.fGap;
