    }
    java.awt.Insets insets = target.getInsets();
    dim.width += insets.left + insets.right;
    dim.width += 2 * this.fBorder.x;
    dim.height += insets.top + insets.bottom;
    dim.height += 2 * this.fBorder.y;
    return dim;
