    java.lang.String filename = dialog.getFile();
    if (filename != null) {
        filename = this.stripTrailingAsterisks(filename);
        java.lang.String dirname = dialog.getDirectory();
        path = dirname + filename;
    }
    dialog.dispose();
    return path;
}

